// Generates src/generated/*.ts from the pinned synthwerk-contracts specs in contracts/.
//
//   node scripts/codegen.ts                 regenerate from the vendored specs
//   node scripts/codegen.ts --sync <dir>    copy the specs at the pinned commit from a
//                                           local synthwerk-contracts clone, then regenerate
//
// To move the pin: change "commit" in contracts/contracts.lock.json, run --sync, commit.
// tests/unit/sdk/codegen.test.ts fails when a vendored spec or a generated file drifts.
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'
import ts from 'typescript'

export const packageDir = join(dirname(fileURLToPath(import.meta.url)), '..')
export const contractsDir = join(packageDir, 'contracts')
export const generatedDir = join(packageDir, 'src', 'generated')

export interface ContractsLock {
  repository: string
  commit: string
  files: Record<string, { path: string; sha256: string }>
}

export function readLock(): ContractsLock {
  return JSON.parse(
    readFileSync(join(contractsDir, 'contracts.lock.json'), 'utf8')
  ) as ContractsLock
}

export function sha256(text: string): string {
  return createHash('sha256').update(text).digest('hex')
}

/** Output file name for a vendored spec: llm.yaml -> llm.ts. */
export function outputName(specFile: string): string {
  return specFile.replace(/\.yaml$/, '.ts')
}

const BLOB = ts.factory.createTypeReferenceNode(ts.factory.createIdentifier('Blob'))

/**
 * `format: binary` is a file part of a multipart body (the vision `image` field). The default
 * type is `string`; a browser sends a Blob (a File is a Blob).
 */
function binaryAsBlob(schema: { format?: string }): ts.TypeNode | undefined {
  return schema.format === 'binary' ? BLOB : undefined
}

/** The generated TypeScript for one vendored spec. Deterministic: same input, same output. */
export async function generate(specFile: string, lock: ContractsLock): Promise<string> {
  const entry = lock.files[specFile]
  if (!entry) throw new Error(`codegen: ${specFile} is not in contracts.lock.json`)
  const source = readFileSync(join(contractsDir, specFile), 'utf8')
  const ast = await openapiTS(source, { transform: binaryAsBlob })
  const banner = [
    '// Generated by packages/sdk/scripts/codegen.ts. Do not edit.',
    `// Source: ${lock.repository} @ ${lock.commit}`,
    `// File: ${entry.path}`,
    ''
  ].join('\n')
  return `${banner}\n${astToString(ast)}`
}

function sync(clone: string, lock: ContractsLock): void {
  for (const [specFile, entry] of Object.entries(lock.files)) {
    const text = execFileSync('git', ['-C', clone, 'show', `${lock.commit}:${entry.path}`], {
      encoding: 'utf8'
    })
    writeFileSync(join(contractsDir, specFile), text)
    entry.sha256 = sha256(text)
  }
  writeFileSync(join(contractsDir, 'contracts.lock.json'), `${JSON.stringify(lock, null, 2)}\n`)
}

async function main(argv: string[]): Promise<void> {
  const lock = readLock()
  const syncAt = argv.indexOf('--sync')
  if (syncAt !== -1) {
    const clone = argv[syncAt + 1] ?? join(packageDir, '..', '..', '..', 'synthwerk-contracts')
    sync(clone, lock)
  }
  for (const specFile of Object.keys(lock.files)) {
    const text = readFileSync(join(contractsDir, specFile), 'utf8')
    const expected = lock.files[specFile]?.sha256
    if (sha256(text) !== expected) {
      throw new Error(
        `codegen: contracts/${specFile} does not match its sha256 in contracts.lock.json`
      )
    }
    writeFileSync(join(generatedDir, outputName(specFile)), await generate(specFile, lock))
    console.log(`codegen: src/generated/${outputName(specFile)}`)
  }
}

if (import.meta.main) await main(process.argv.slice(2))
